{
  "mechanisms": [
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "First-stage Q-values are updated by the second-stage reward prediction error scaled by an eligibility trace decay parameter.",
      "params": [
        {
          "name": "lambda_param",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1[action_1[trial]] += learning_rate * (delta_1 + lambda_param * delta_2)",
      "expressible_in_slots": true
    },
    {
      "name": "reward_dependent_stickiness",
      "title": "Reward-Dependent Stickiness",
      "description": "Applies a stickiness bonus to the previously chosen actions in both stages (tracked per state for stage 2), where the bonus magnitude depends on whether the previous trial resulted in a reward.",
      "params": [
        {
          "name": "stick_win",
          "bounds": [0, 5]
        },
        {
          "name": "stick_loss",
          "bounds": [0, 5]
        }
      ],
      "evidence": "bonus = stick_win if last_reward_1 == 1 else stick_loss\n            q_net_1[last_action_1] += bonus\n...\nbonus = stick_win if last_reward_2[state_idx] == 1 else stick_loss\n            q_net_2[last_action_2[state_idx]] += bonus",
      "expressible_in_slots": true
    }
  ]
}
